// plain_circuits.js -- control circuits that are not pump stations, as a model writes them (area B). Each is built on
// 1.24.30 and compared with what 1.24.29 made of it (plain_1229.json, written by make_plain_1229.js from
// `git show lantern-1.24.29:src/lantern.inner.html`, loaded the same way).
module.exports = [
  { id: "B-motor-starter", q: "Draw a motor starter control circuit with start and stop buttons and a run light.", b: "MAKE CONTROL: Motor starter\nstop PB1\nstart PB2 M1\ncoil M1 \"motor starter\"\nlamp LT1 M1 \"run\" green\nEND" },
  { id: "B-motor-starter-ol", q: "Draw a three-wire motor control circuit with an overload.", b: "MAKE CONTROL: Three-wire control\nstop PB1 M1\nstart PB2 M1\noverload OL1 M1\ncoil M1 \"motor starter\"\nEND" },
  { id: "B-fwd-rev", q: "Draw a forward/reverse motor starter control circuit with interlocks.", b: "MAKE CONTROL: Forward reverse\nstop PB1\nstart PB2 M1\nstart PB3 M2\ncoil M1 \"forward\"\ncoil M2 \"reverse\"\nlamp LT1 M1 \"forward\" green\nlamp LT2 M2 \"reverse\" amber\nEND" },
  { id: "B-fwd-rev-interlock-written", q: "Draw a reversing motor starter control circuit.", b: "MAKE CONTROL: Reversing starter\nstop PB1\nstart PB2 M1\nstart PB3 M2\ncoil M1 \"forward\"\ncoil M2 \"reverse\"\ninterlock M1 M2\nEND" },
  { id: "B-conveyor-limit", q: "Draw the control circuit for a conveyor motor that stops at a limit switch.", b: "MAKE CONTROL: Conveyor\nstop PB1 M1\nstart PB2 M1\nlimit LS1 M1 nc\ncoil M1 \"conveyor starter\"\nlamp LT1 M1 \"running\" green\nEND" },
  { id: "B-sump-one-float", q: "Draw a control circuit for a sump pump switched by one float switch.", b: "MAKE CONTROL: Sump pump\nswitch SS1 M1 \"hand\"\nfloat FS1 M1\ncoil M1 \"pump starter\"\nlamp LT1 M1 \"pump on\" green\nEND" },
  { id: "B-sump-float-labelled", q: "Draw a control circuit for a sump pump with a float switch.", b: "MAKE CONTROL: Sump pump\nfloat FS1 M1 \"pump on\"\ncoil M1 \"pump starter\"\nEND" },
  { id: "B-tank-fill-solenoid", q: "Draw a control circuit for filling a tank with a solenoid valve and a high level float switch.", b: "MAKE CONTROL: Tank fill\nstop PB1 CR1\nstart PB2 CR1\nfloat FS1 CR1 nc \"tank full\"\ncoil CR1 \"fill relay\"\nsolenoid SOL1 CR1 \"fill valve\"\nlamp LT1 CR1 \"filling\" green\nEND" },
  { id: "B-sequence-timer", q: "Draw a control circuit where a timer starts a second motor 10 seconds after the first.", b: "MAKE CONTROL: Sequence start\nstop PB1\nstart PB2 M1\ncoil M1 \"motor 1 starter\"\ntimer TR1 M1 \"10 s\"\ncoil M2 TR1 \"motor 2 starter\"\nEND" },
  { id: "B-jog-not-drawn", q: "Draw a motor starter with a jog button.", b: "MAKE CONTROL: Jog\nstop PB1\nstart PB2 M1\njog PB3 M1\ncoil M1 \"starter\"\nEND" },
  { id: "B-estop", q: "Draw a motor control circuit with an emergency stop and a start/stop station.", b: "MAKE CONTROL: E-stop\nestop ES1\nstop PB1 M1\nstart PB2 M1\ncoil M1 \"motor starter\"\nEND" },
  { id: "B-compressor-pressure", q: "Draw the control circuit for an air compressor motor with a pressure switch.", b: "MAKE CONTROL: Compressor\nstop PB1\nstart PB2 CR1\ncoil CR1 \"control relay\"\npressure PS1 M1 nc\ncoil M1 CR1 \"compressor starter\"\nEND" },
  { id: "B-temp-alarm-horn", q: "Draw a control circuit with a high temperature alarm horn.", b: "MAKE CONTROL: Temperature alarm\ntemp TS1 AH1\nhorn AH1 \"high temperature\"\nlamp LT1 TS1 \"high temp\" red\nEND" },
  { id: "B-alternate-source-relay", q: "Draw a relay control circuit with an alternate source relay that picks up when the main supply is lost.", b: "MAKE CONTROL: Alternate source\ncoil CR1 \"main supply relay\"\nswitch SS1 CR1 \"main on\"\ncoil CR2 CR1 off \"alternate source relay\"\nlamp LT1 CR2 \"on alternate\" amber\nEND" },
  { id: "B-alternating-flasher", q: "Draw a control circuit with an alternating flasher for two warning lamps.", b: "MAKE CONTROL: Flasher\nswitch SS1 CR1 \"on\"\ncoil CR1 \"alternating flasher\"\nlamp LT1 CR1 \"left\" red\nlamp LT2 CR1 off \"right\" red\nEND" },
  { id: "B-two-pumps-own-buttons", q: "Draw a control circuit for two pumps, each with its own start and stop buttons.", b: "MAKE CONTROL: Two pumps\nstop PB1 M1\nstart PB2 M1\nstop PB3 M2\nstart PB4 M2\ncoil M1 \"pump 1 starter\"\ncoil M2 \"pump 2 starter\"\nEND" },
  { id: "B-drill-press-24vdc", q: "Draw a motor starter for a drill press with a 24 V DC control supply.", b: "MAKE CONTROL: Drill press\nsupply \"24 V DC\"\nstop PB1\nstart PB2 K1\ncoil K1 \"contactor\"\nlamp LT1 K1 \"run\" green\nEND" },
  { id: "B-fan-hoa-thermostat", q: "Draw a control circuit for an exhaust fan with a hand-off-auto switch and a thermostat.", b: "MAKE CONTROL: Exhaust fan\nswitch SS1 M1 \"hand-off-auto\"\ntemp TS1 M1\ncoil M1 \"fan starter\"\nEND" },
  { id: "B-overload-trip-light", q: "Draw a motor starter with an overload trip light.", b: "MAKE CONTROL: Starter\nstop PB1\nstart PB2 M1\noverload OL1 M1\ncoil M1 \"motor starter\"\nlamp LT1 OL1 \"overload tripped\" amber\nEND" },
  { id: "B-stopped-light", q: "Draw a motor starter with a stopped light.", b: "MAKE CONTROL: Starter\nstop PB1\nstart PB2 M1\ncoil M1 \"motor starter\"\nlamp LT1 M1 off \"stopped\" red\nEND" },
  { id: "B-two-hand-press", q: "Draw a relay control circuit for a press that needs two buttons pressed together.", b: "MAKE CONTROL: Two-hand control\nbutton PB1 CR1 \"left hand\"\nbutton PB2 CR1 \"right hand\"\ncoil CR1 \"press relay\"\nsolenoid SOL1 CR1 \"press valve\"\nEND" },
  { id: "B-wye-delta-not-drawn", q: "Draw a star-delta motor starter control circuit.", b: "MAKE CONTROL: Star delta\nstop PB1\nstart PB2 M1\nstar-delta KM2 M1\ncoil M1 \"main contactor\"\nEND" },
];
